REVOKE ALL ON SCHEMA public FROM PUBLIC;
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM PUBLIC;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA public FROM PUBLIC;
GRANT USAGE ON SCHEMA public TO v_school_management_runtime;
GRANT USAGE,CREATE ON SCHEMA public TO v_school_management_migration;
DO $$ BEGIN EXECUTE format('REVOKE CONNECT,CREATE,TEMPORARY ON DATABASE %I FROM PUBLIC',current_database()); END $$;
DO $$ BEGIN EXECUTE format('GRANT CONNECT ON DATABASE %I TO v_school_management_runtime,v_school_management_migration',current_database()); END $$;
GRANT SELECT,INSERT ON "school","school_operation","branch","school_membership","membership_permission_grant","student_enrollment","enrollment_status_history","training_group","student_group_membership","teacher_group_assignment","group_roster_revision","group_roster_member","school_invitation" TO v_school_management_runtime;
GRANT UPDATE("name","status","revision","updated_at") ON "school" TO v_school_management_runtime;
GRANT UPDATE("name","address_line","city","postal_code","country_code","status","revision","last_operation_id") ON "branch" TO v_school_management_runtime;
GRANT UPDATE("role","started_at","ended_at","revision","last_operation_id") ON "school_membership" TO v_school_management_runtime;
GRANT UPDATE("membership_id","permission","started_at","ended_at","granted_operation_id","ended_operation_id") ON "membership_permission_grant" TO v_school_management_runtime;
GRANT UPDATE("student_id","category_code","started_at","ended_at","status","status_changed_at","revision","last_operation_id") ON "student_enrollment" TO v_school_management_runtime;
GRANT UPDATE("branch_id","name","category_code","started_at","ended_at","revision","membership_revision","last_operation_id") ON "training_group" TO v_school_management_runtime;
GRANT UPDATE("enrollment_id","group_id","joined_at","left_at","association_program_version_id","association_verified_at","revision","last_operation_id") ON "student_group_membership" TO v_school_management_runtime;
GRANT UPDATE("teacher_id","group_id","assigned_at","ended_at","revision","last_operation_id") ON "teacher_group_assignment" TO v_school_management_runtime;
GRANT UPDATE("target_user_id","role","category_code","issuer_membership_id","status","revision","expires_at","issued_operation_id","accepted_operation_id","accepted_at","result_membership_id","result_enrollment_id","revoked_operation_id","revoked_at") ON "school_invitation" TO v_school_management_runtime;
GRANT UPDATE(status,resolved_at,resulting_revision,resulting_school_revision,outcome_code) ON school_operation TO v_school_management_runtime;
DO $secure$ DECLARE f record; BEGIN
 FOR f IN SELECT p.oid::regprocedure AS signature FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prokind='f' AND NOT EXISTS(SELECT 1 FROM pg_depend dep WHERE dep.classid='pg_proc'::regclass AND dep.objid=p.oid AND dep.deptype='e') LOOP
  EXECUTE format('ALTER FUNCTION %s SET search_path=pg_catalog,public,pg_temp',f.signature);
 END LOOP;
END $secure$;
ALTER TABLE "school" ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_scope ON "school" TO v_school_management_runtime USING (school_id=nullif(current_setting('vairas.school_id',true),'')::uuid) WITH CHECK (school_id=nullif(current_setting('vairas.school_id',true),'')::uuid);
